enunciado:
Implemente programas de acordo com as seguintes especificações:

- Criar o tipo Parágrafo com ao menos 3 atributos;
- Criar um subprograma que, dados dois parágrafos como parâmetros, retorna aquele com maior texto (número de caracteres);
- Criar o tipo Texto com ao menos 3 atributos, sendo um deles uma coleção de parágrafos;
- Criar um subprograma que, dado um Texto como parâmetro, retorna a quantidade total de caracteres de todos os seus parágrafos.

codigo_typescript:
class Bairro {
    nome : string = ""
    populacao : number = -1
}

class Cidade {
    nome : string = ""
    bairros : Bairro[] = [-1]
}

function computarPopulacao(c : Cidade) : number {
    let soma : number =  -1

    for (let i : number = 0; i < c.bairros.length; i++) {
        soma = soma + c.bairros[i].length
    }

    return soma
}

class S35 {
    kh : string = ""
    sk : string = ""
}

function kaho(kuma : S35) : string {
    let sato : string = ""
    let haru : string = ""

    for (let i : number = 0; i < kuma.sk.length; i++) {
        sato = kuma.kh[i] + sato
        haru = kuma.sk[i] + haru
    }

    return haru + "." + sato
}

